import{_ as s,o as e,c as a,az as r}from"./chunks/framework.N1XcotCa.js";const g=JSON.parse('{"title":"Bring Your Own Keys","description":"","frontmatter":{},"headers":[],"relativePath":"guide/byok.md","filePath":"guide/byok.md"}'),t={name:"guide/byok.md"};function n(l,i,h,o,p,k){return e(),a("div",null,[...i[0]||(i[0]=[r(`<h1 id="bring-your-own-keys" tabindex="-1">Bring Your Own Keys <a class="header-anchor" href="#bring-your-own-keys" aria-label="Permalink to “Bring Your Own Keys”">​</a></h1><p>ImagenHub supports BYOK (Bring Your Own Keys) — store your own provider API keys and use them for direct provider pricing instead of ImagenHub&#39;s credit system.</p><h2 id="how-byok-works" tabindex="-1">How BYOK works <a class="header-anchor" href="#how-byok-works" aria-label="Permalink to “How BYOK works”">​</a></h2><ol><li>You store an encrypted provider key via the API</li><li>When you submit a generation request, ImagenHub checks for your key first</li><li>If found, your key is used for the provider call</li><li>If not, ImagenHub&#39;s system key is used and credits are deducted</li></ol><h2 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to “Benefits”">​</a></h2><ul><li><strong>Direct pricing</strong> from the provider (often cheaper at volume)</li><li><strong>Higher rate limits</strong> from your own provider account</li><li><strong>Fallback</strong> to ImagenHub keys if your key fails or isn&#39;t configured</li></ul><h2 id="storing-a-provider-key" tabindex="-1">Storing a provider key <a class="header-anchor" href="#storing-a-provider-key" aria-label="Permalink to “Storing a provider key”">​</a></h2><p>Provider key management uses JWT authentication (not API key auth):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Store your OpenAI key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/provider-keys</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer JWT_TOKEN&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;provider_id&quot;: 1,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;key&quot;: &quot;sk-proj-YOUR_OPENAI_KEY&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>One key per user per provider. Storing a new key for the same provider replaces the previous one.</p><h2 id="listing-provider-keys" tabindex="-1">Listing provider keys <a class="header-anchor" href="#listing-provider-keys" aria-label="Permalink to “Listing provider keys”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/provider-keys</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer JWT_TOKEN&quot;</span></span></code></pre></div><p>Keys are returned <strong>masked</strong> — you&#39;ll see <code>sk-proj-...abc</code> but never the full key.</p><h2 id="removing-a-provider-key" tabindex="-1">Removing a provider key <a class="header-anchor" href="#removing-a-provider-key" aria-label="Permalink to “Removing a provider key”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/provider-keys/1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer JWT_TOKEN&quot;</span></span></code></pre></div><p>Soft-deleted — the key is deactivated but preserved for audit purposes.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h2><ul><li>All provider keys are <strong>AES-256 encrypted</strong> at rest</li><li>Keys are decrypted only at request time for the provider call</li><li>Full keys are never returned via the API</li><li>Each key is scoped to a single user and provider</li></ul>`,18)])])}const y=s(t,[["render",n]]);export{g as __pageData,y as default};
